om the public - Federal securities (in millions)\nvalues = {\n    2016: 1419286,\n    2017: 666472,\n    2018: 1258348,\n    2019: 1208690,\n    2020: 4234396,\n    2021: 1484000,\n    2022: 2453245,\n    2023: 2150233,\n    2024: 2241060\n}\n\n# Calculate natural log for each year\nlogs = sorted([math.log(val) for val in values.values()])\n\nprint(\"Testing different interpretations of 20% trimmed mean:\")\nprint(f\"Total values: {len(logs)}\")\n\n# Option 1: trim 1 from each end (keeping 7)\ntrim1 = logs[1:-1]\nmean1 = sum(trim1)/len(trim1)\nprint(f\"\\nOption 1 - Trim 1 from each end ({len(trim1)} values): {mean1:.6f}\")\n\n# Option 2: trim 2 from each end (keeping 5) - rounding 1.8 to 2\ntrim2 = logs[2:-2]\nmean2 = sum(trim2)/len(trim2)\nprint(f\"Option 2 - Trim 2 from each end ({len(trim2)} values): {mean2:.6f}\")\n\n# Which is closer to 20%?\nprint(f\"\\nOption 1: {1/9*100:.1f}% trimmed from each end\")\nprint(f\"Option 2: {2/9*100:.1f}% trimmed from each end\")\nprint(f\"20% trimmed mean should be closer to Option 2 (22.2% each)\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
